select cus_batch
from b_marketing_sync_info
where api_code = #{apiCode}
 and create_time >= #{beginTime} and create_time < #{endTime}  
group by cus_batch

select min(id)
from b_marketing_sync_info
where api_code = #{apiCode}
  and cus_batch = #{cusBatch}
  and status in (2,4)
 and create_time >= #{beginTime} and create_time < #{endTime}

select *
from b_marketing_sync_info
where api_code = #{apiCode}
  and cus_batch = #{cusBatch}
  and status in (2,4)
  and id >=#{id}
and create_time >= #{beginTime} and create_time < #{endTime}  
order by id asc limit 200

select count(1)
from b_marketing_transfer_${apiCode}
where request_id = #{requestId}

select min(id)
from b_marketing_sync_${apiCode}
where  applet_time >= #{sTimeStr} and applet_time < #{eTimeStr} 
and is_repeat in (1,2)
and (${whereStr})

select max(id)
from b_marketing_sync_${apiCode}
where  applet_time >= #{sTimeStr} and applet_time < #{eTimeStr} 
and is_repeat in (1,2)
and (${whereStr})

select count(1)
from b_marketing_sync_${apiCode}
where  applet_time >= #{sTimeStr}and applet_time < #{eTimeStr} 
and is_repeat in (1,2)
  and (${whereStr})

select *
from b_marketing_sync_${apiCode}
where  applet_time >= #{sTimeStr} and applet_time < #{eTimeStr} and id >= #{minId} and id <= #{maxId}
and is_repeat in (1,2)
and (${whereStr}) order by id asc

